sys_script_client.script:
function onLoad() {

    //Display error message on the form when swift or position attribute sync values is error.
    if (g_form.getValue('position_attribute_sync') === 'Response Un-Successful - Error') {
        g_form.addErrorMessage('Holdings Data sync was not completed due to technical error. Please check the holdings manually. The technical issue has been reported to HSBC technical team.');
    } else if (g_form.getValue('position_attribute_sync') === 'Response Un-Successful-400 Client Error') { //7426
        g_form.addErrorMessage('Holdings Data sync was not completed due to token issue. Please contact the IT team for further assistance.');
    } else if (g_form.getValue('position_attribute_sync') === 'Response Un-Successful-500 Server Error') {
        g_form.addErrorMessage('Holdings Data sync was not completed due to upstream issue.  Please contact the IT team for further assistance.');
    }
    if (g_form.getValue('swift_attribute_sync') === 'Response Un-Successful - Error') {
        g_form.addErrorMessage('Swift Message Data sync was not completed due to technical error. Please check the messages manually. The technical issue has been reported to HSBC technical team.');
    } else if (g_form.getValue('swift_attribute_sync') === 'Response Un-Successful-400 Client Error') { //7426
        g_form.addErrorMessage('Swift Message Data sync was not completed due to token issue. Please retry after sometime.');
    } else if (g_form.getValue('swift_attribute_sync') === 'Response Un-Successful-500 Server Error') {
        g_form.addErrorMessage('Swift Message Data sync was not completed due to upstream issue.  Please contact the IT team for further assistance.');
    }
    /*else{
    	g_form.clearMessages();
    }*/

}
